using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes the input message back to the caller.")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }

    [McpServerTool, Description("Returns the current server time.")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("O");
    }
}

using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

public class ConfigResourceProvider
{
    private static readonly Dictionary<string, object> _configData = new()
    {
        ["appName"] = "McpHttpServer",
        ["version"] = "1.0.0",
        ["environment"] = "development",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false,
        }
    };

    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        Description = "Returns the application configuration data.")]
    public static string GetAppSettings()
    {
        return JsonSerializer.Serialize(_configData, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features", Name = "Feature Flags",
        Description = "Returns the current feature flag settings.")]
    public static string GetFeatureFlags()
    {
        var features = (Dictionary<string, bool>)_configData["features"];
        return JsonSerializer.Serialize(features, new JsonSerializerOptions { WriteIndented = true });
    }
}

